import { Button, Dropdown, Loading, useModal } from '@nextui-org/react';
import { useState } from 'react';
import { getLang } from '../utils/getLang';
import userStore from '../stores/user.store';
import { observer } from 'mobx-react-lite';
import CoinHistory from './CoinHistory';
import OrderModal from './OrderModal';

export const LoginButton = observer(() => {
  const { visible: showCoinHistory, setVisible: setShowCoinHistory } =
    useModal(false);

  const [showOrderModal, setShowOrderModal] = useState(false);
  const formatString = (str: string, len: number) => {
    if (str.length > len) {
      return str.substring(0, len) + '...';
    }
    return str;
  };

  if (!userStore.session?.user && userStore.loading) {
    return <Loading size="xs" />;
  }
  return userStore.session.user ? (
    <div
      style={{
        display: 'flex',
        gap: '5px',
        alignItems: 'center',
      }}
    >
      {showCoinHistory ? (
        <CoinHistory
          onClose={() => {
            setShowCoinHistory(false);
          }}
        />
      ) : null}

      {showOrderModal ? (
        <OrderModal
          onClose={() => {
            setShowOrderModal(false);
          }}
        />
      ) : null}
      <Dropdown>
        <Dropdown.Button
          size="xs"
          auto
          flat
          color="warning"
          style={{
            fontSize: '12px',
            fontWeight: 'normal',
            color: '#333',
            background: '#efefef',
          }}
        >
          $GPTCoin: {getLang('lang') == 'en' ? 'Free' : '赠送'}{' '}
          {(userStore.session.user as any).freeQuota} |{' '}
          {getLang('lang') == 'en' ? 'Buy' : '购买'}{' '}
          {(userStore.session.user as any).buyQuota}
        </Dropdown.Button>
        <Dropdown.Menu
          color="primary"
          selectionMode="single"
          containerCss={{
            zIndex: '999999999999',
          }}
        >
          <Dropdown.Item
            key="profile"
            css={{
              fontSize: '14px',
            }}
            withDivider={true}
          >
            👤 {formatString(userStore.session.user?.name || '', 20)}
          </Dropdown.Item>
          <Dropdown.Item
            key="buy"
            css={{
              fontSize: '12px',
            }}
          >
            <a
              href={'https://zhinang.ai/order'}
              target="_blank"
              style={{
                color: 'inherit',
                display: 'block',
                textDecoration: 'none',
              }}
            >
              💸{' '}
              {getLang('lang') == 'en' ? 'Buy $GPTCoin' : '购买 $GPTCoin 代币'}
            </a>
          </Dropdown.Item>

          {/*<Dropdown.Item*/}
          {/*  withDivider*/}
          {/*  css={{*/}
          {/*    fontSize: '12px',*/}
          {/*  }}*/}
          {/*>*/}
          {/*  <a*/}
          {/*    href="https://gptnow-im.gitbook.io/user-manual/quota/about-free-quota"*/}
          {/*    target="_blank"*/}
          {/*    rel="noreferrer"*/}
          {/*    style={{*/}
          {/*      color: 'inherit',*/}
          {/*      display: 'block',*/}
          {/*      textDecoration: 'none',*/}
          {/*    }}*/}
          {/*  >*/}
          {/*    💰 About $GPTCoin*/}
          {/*  </a>*/}
          {/*</Dropdown.Item>*/}
          <Dropdown.Item
            css={{
              fontSize: '12px',
            }}
          >
            <a
              onClick={() => {
                setShowCoinHistory(true);
              }}
              style={{
                color: 'inherit',
                display: 'block',
                textDecoration: 'none',
              }}
            >
              📈 $GPTCoin {getLang('lang') == 'en' ? 'History' : '历史'}
            </a>
          </Dropdown.Item>

          <Dropdown.Item
            key="website"
            css={{
              fontSize: '12px',
            }}
          >
            <a
              href="https://ZhiNang.ai"
              style={{
                color: 'inherit',
                display: 'block',
                textDecoration: 'none',
              }}
            >
              🌐 https://ZhiNang.ai
            </a>
          </Dropdown.Item>

          <Dropdown.Item
            key="logout"
            withDivider
            css={{
              fontSize: '12px',
            }}
          >
            <a
              href="https://zhinang.ai/api/auth/signout"
              style={{
                color: 'inherit',
                display: 'block',
                textDecoration: 'none',
              }}
            >
              🚶‍♂️ {getLang('lang') == 'en' ? 'Logout' : '退出登录'}
            </a>
          </Dropdown.Item>
        </Dropdown.Menu>
      </Dropdown>
    </div>
  ) : (
    <div
      style={{
        display: 'flex',
        gap: '5px',
      }}
    >
      <Button
        size="xs"
        auto
        flat
        onClick={() => {
          window.location.href = 'https://zhinang.ai/api/auth/signin';
        }}
      >
        {getLang('login')}
      </Button>
    </div>
  );
});
