#chatgpt-anywhere-container * {
  font-family: Montserrat, Inter, Roboto, -apple-system, BlinkMacSystemFont, PingFang SC, Microsoft YaHei, sans-serif !important;
}

#chatgpt-anywhere-trigger {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: 2147483647;
  height: 25px;
  width: 25px;
  text-align: center;
  line-height: 23px;
  font-size: 12px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: content-box;
  pointer-events: all;
}

#chatgpt-anywhere-trigger:hover,
#chatgpt-anywhere-trigger.hover {
  background-color: rgb(255, 255, 255);
  color: rgb(30, 30, 30);
}

#chatgpt-anywhere-trigger:hover #chatgpt-anywhere-trigger-content {
  animation: hover_animate 0.3s ease 0s 1 normal both;
}

#chatgpt-anywhere-trigger.hover #chatgpt-anywhere-trigger-content {
  animation: hover_animate 0.3s ease 0s 1 normal both;
}

@keyframes hover_animate {
  0% {
    transform: scale(1);
    border-radius: 0%;
  }
  100% {
    transform: scale(1.4);
    border-radius: 50%;
  }
}
@keyframes display_anywhere_trigger {
  0% {
    opacity: 0;
    transform: translateY(500px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes huxi_animate {
  0% {
    border-radius: 0%;
    transform: scale(1.2);
  }
  50% {
    border-radius: 30%;
    transform: scale(0.8);
  }
  100% {
    border-radius: 0%;
    transform: scale(1.2);
  }
}
#chatgpt-anywhere-container {
  animation: display_anywhere_trigger 0.8s ease 0s 1 normal forwards;
}

#chatgpt-anywhere-trigger-content {
  width: 100%;
  height: 100%;
  background-color: rgb(30, 30, 30);
  animation: huxi_animate 6s ease-in-out 0.2s infinite forwards;
  overflow: hidden;
  border: 1px solid #fff;
}
#chatgpt-anywhere-trigger-content img {
  width: 100%;
  height: 100%;
  -webkit-user-drag: none;
  display: block;
