import { Modal, Table, Text } from '@nextui-org/react';
import moment from 'moment';
import { useEffect, useState } from 'react';
import { getToken } from '../utils/getToken';

export default function CoinHistory(props: { onClose: () => void }) {
  const [data, setData] = useState<
    {
      id: number;
      count: number;
      source: string;
      createdAt: string;
    }[]
  >([]);
  const [loading, setLoading] = useState(false);
  const [total, setTotal] = useState(0);
  const [pageIndex, setPageIndex] = useState(1);
  const [pageSize, setPageSize] = useState(10);

  async function loadCoinHistory() {
    setLoading(true);
    const token = await getToken();
    const res = await fetch('https://zhinang.ai/api/coin-history', {
      method: 'POST',
      body: JSON.stringify({
        pageIndex,
        pageSize,
      }),
      //@ts-ignore
      headers: {
        'Content-Type': 'application/json',
        token,
      },
    });
    const json = await res.json();
    setData(json.records);
    setTotal(json.total);
    setLoading(false);
  }

  useEffect(() => {
    loadCoinHistory();
  }, []);

  return (
    <Modal
      open={true}
      onClose={() => {
        props.onClose();
      }}
      css={{
        height: '500px',
      }}
      width="600px"
      title="$GPTCoin history"
      closeButton={true}
    >
      <Modal.Header>
        <Text id="modal-title" size={18}>
          $GPTCoin history
        </Text>
      </Modal.Header>
      <Table
        containerCss={{
          height: '100%',
        }}
      >
        <Table.Header>
          <Table.Column>amount</Table.Column>
          <Table.Column>type</Table.Column>
          <Table.Column>time</Table.Column>
        </Table.Header>

        <Table.Body loadingState={loading ? 'loading' : undefined}>
          {data.map((d) => {
            return (
              <Table.Row key={d.id}>
                <Table.Cell
                  css={{
                    textAlign: 'left',
                  }}
                >
                  {d.count}
                </Table.Cell>
                <Table.Cell
                  css={{
                    textAlign: 'left',
                  }}
                >
                  {d.source}
                </Table.Cell>
                <Table.Cell
                  css={{
                    textAlign: 'left',
                  }}
                >
                  {moment(d.createdAt).format('YYYY-MM-DD HH:mm:ss')}
                </Table.Cell>
              </Table.Row>
            );
          })}
        </Table.Body>
        <Table.Pagination
          noMargin
          align="center"
          rowsPerPage={pageSize}
          onPageChange={(page) => {
            setPageIndex(page);
            loadCoinHistory();
          }}
        />
      </Table>
    </Modal>
  );
}
