import { Button, Card, Grid, Loading, Modal, Text } from '@nextui-org/react';
import { useState } from 'react';
import toast from 'react-hot-toast';
import { getToken } from '../utils/getToken';

export default function CoinHistory(props: { onClose: () => void }) {
  const [data, setData] = useState<
    {
      id: number;
      count: number;
      source: string;
      createdAt: string;
    }[]
  >([]);
  const [loading, setLoading] = useState(false);
  const [total, setTotal] = useState(0);
  const [pageIndex, setPageIndex] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const list = [
    // {
    //   title: '1000 $GPTCoin',
    //   img: '/images/fruit-1.jpeg',
    //   price: '$1.4',
    //   key: 'coin_1000',
    // },
    {
      title: '5000 $GPTCoin',
      img: '/images/fruit-2.jpeg',
      price: '$5.7/￥39.99',
      key: 'coin_5000',
    },
    {
      title: '10000 $GPTCoin',
      img: '/images/fruit-3.jpeg',
      price: '$9.9/￥79.99',
      key: 'coin_10000',
    },
  ];

  const [loading1, setLoading1] = useState(false);
  const [loading2, setLoading2] = useState(false);
  const [loading3, setLoading3] = useState(false);

  async function buyCoin(key: 'coin_1000' | 'coin_5000' | 'coin_10000') {
    if (key == 'coin_1000') {
      setLoading1(true);
    } else if (key == 'coin_5000') {
      setLoading2(true);
    } else if (key == 'coin_10000') {
      setLoading3(true);
    }
    const token = await getToken();
    const res = await fetch('https://zhinang.ai/api/order', {
      method: 'POST',
      body: JSON.stringify({
        orderType: key,
      }),
      //@ts-ignore
      headers: {
        'Content-Type': 'application/json',
        token,
      },
    });
    const json = await res.json();
    if (json.url) {
      window.location.href = json.url;
    } else {
      toast.error('System error');
    }
    if (key == 'coin_1000') {
      setLoading1(false);
    } else if (key == 'coin_5000') {
      setLoading2(false);
    } else if (key == 'coin_10000') {
      setLoading3(false);
    }
  }

  return (
    <Modal
      open={true}
      onClose={() => {
        props.onClose();
      }}
      width="800px"
      title="$GPTCoin history"
      closeButton={true}
    >
      <Modal.Header>
        <Text id="modal-title" size={18} b>
          Buy $GPTCoin
        </Text>
      </Modal.Header>
      <Modal.Body>
        <Grid.Container gap={2} justify="flex-start">
          {list.map((item, index) => (
            <Grid xs={4} key={index}>
              <Card isPressable>
                <Card.Body css={{ p: 0 }}>
                  <Card.Image
                    src={'https://nextui.org' + item.img}
                    objectFit="cover"
                    width="100%"
                    height={140}
                    alt={item.title}
                  />
                </Card.Body>
                <Card.Footer css={{ justifyItems: 'flex-start' }}>
                  <div>
                    <div>
                      <Text b size={'xl'}>
                        {item.title}
                      </Text>
                    </div>

                    <div>
                      <Button
                        size="sm"
                        auto
                        style={{
                          marginTop: '10px',
                        }}
                        disabled={
                          item.key == 'coin_1000'
                            ? loading1
                            : item.key == 'coin_5000'
                            ? loading2
                            : item.key == 'coin_10000'
                            ? loading3
                            : false
                        }
                        onClick={() => {
                          buyCoin(item.key as any);
                        }}
                      >
                        {(
                          item.key == 'coin_1000'
                            ? loading1
                            : item.key == 'coin_5000'
                            ? loading2
                            : item.key == 'coin_10000'
                            ? loading3
                            : false
                        ) ? (
                          <Loading
                            type="spinner"
                            color="currentColor"
                            size="sm"
                          />
                        ) : (
                          <>Buy ({item.price})</>
                        )}
                      </Button>
                    </div>
                  </div>
                </Card.Footer>
              </Card>
            </Grid>
          ))}
        </Grid.Container>
        <div
          style={{
            marginTop: '30px',
            textAlign: 'center',
            marginBottom: '30px',
          }}
        >
          <a
            href="https://gptnow-im.gitbook.io/user-manual/quota/about-free-quota"
            target="_blank"
            rel="noreferrer"
            style={{
              color: 'inherit',
            }}
          >
            How to get $GPTCOIN free?
          </a>
        </div>
      </Modal.Body>
    </Modal>
  );
}
