import { Button, Input, Modal, Text, Textarea } from '@nextui-org/react';
import { useContext, useEffect, useState } from 'react';
import toast from 'react-hot-toast';
import { ChatGPTContext } from 'uikit.chat';
import { getToken } from '../utils/getToken';

export default function ShareModal(props: {
  onClose: () => void;
  title: string;
  id: string;
}) {
  const [shareName, setShareName] = useState<string>();

  async function shareGenerate() {
    const loading = toast.loading('Loading...');

    const token = await getToken();
    const res = await fetch('https://zhinang.ai/api/share', {
      method: 'PUT',
      body: JSON.stringify({
        // password: sharePassword,
        id: props.id,
        name: shareName,
        published: true,
      }),
      //@ts-ignore
      headers: {
        'Content-Type': 'application/json',
        token,
      },
    });
    const data = await res.json();
    toast.dismiss(loading);

    toast.success('Make Public Success!');
    window.open('https://zhinang.ai/share/' + props.id);

    setTimeout(() => {
      props.onClose();
    });
  }

  useEffect(() => {
    if (props.title) setShareName(props.title);
  }, [props.title]);
  return (
    <Modal
      open={true}
      width="500px"
      css={{
        zIndex: 9999999,
      }}
    >
      <Modal.Header>
        <Text
          h2
          style={{
            margin: '20px 0',
          }}
        >
          Public Share Conversation
        </Text>
      </Modal.Header>
      <Modal.Body>
        <div
          style={{
            marginTop: '20px',
            width: '100%',
          }}
        >
          <Textarea
            labelPlaceholder="Title"
            size="sm"
            value={shareName}
            onChange={(e) => {
              setShareName(e.target?.value);
            }}
            css={{
              width: '100%',
              display: 'block',
            }}
            autoComplete="off"
          />
        </div>
        {/* <div
          style={{
            marginTop: '20px',
          }}
        >
          <Input
            labelPlaceholder="Password, not required"
            type="password"
            size="sm"
            value={sharePassword}
            onChange={(e) => {
              setSharePassword(e.target?.value);
            }}
            css={{
              width: '100%',
              display: 'block',
            }}
            autoComplete="off"
          />
        </div> */}
      </Modal.Body>
      <Modal.Footer>
        <Button
          auto
          onPress={() => {
            shareGenerate();
          }}
        >
          Make Public
        </Button>
      </Modal.Footer>
    </Modal>
  );
}
